/* Gen2Recomped PS5: LuaJIT FFI symbol lookup in a static title.
 *
 * ffi.C.<name> resolves through dlsym(RTLD_DEFAULT, name). The title is one
 * static executable that exports nothing, and a title's dlsym/dlopen are not
 * worth trusting (an import the system cannot resolve is a null call), so the
 * link wraps them (--wrap=dlsym,dlopen,dlerror,dlclose,dladdr) and answers from a
 * table instead: every PHYSFS_* function of LOVE's PhysFS plus the libc
 * functions listed in ports/ps5/launcher/ffi_exports.txt. The table itself,
 * g2r_ffi_exports[], is generated by scripts/ps5/build_runtime.sh.
 *
 * ffi.load() of anything fails cleanly with an error message. */
#include <stddef.h>
#include <string.h>

struct g2r_ffi_export {
    const char *name;
    void *address;
};

extern const struct g2r_ffi_export g2r_ffi_exports[];
extern const size_t g2r_ffi_export_count;

static const char *g2r_dlerror_message;

void *__wrap_dlsym(void *handle, const char *name)
{
    (void)handle;
    if (name != NULL) {
        for (size_t i = 0; i < g2r_ffi_export_count; i++) {
            if (strcmp(g2r_ffi_exports[i].name, name) == 0)
                return g2r_ffi_exports[i].address;
        }
    }
    g2r_dlerror_message = "symbol not exported by the PS5 title";
    return NULL;
}

void *__wrap_dlopen(const char *path, int mode)
{
    (void)path;
    (void)mode;
    g2r_dlerror_message = "no dynamic libraries in the PS5 title";
    return NULL;
}

char *__wrap_dlerror(void)
{
    const char *message = g2r_dlerror_message;
    g2r_dlerror_message = NULL;
    return (char *)message;
}

int __wrap_dlclose(void *handle)
{
    (void)handle;
    return 0;
}

/* OpenSSL (libcrypto's DSO code, linked in for love.system.httpDownload)
 * asks dladdr which library an address belongs to. The payload SDK's libc.a
 * answers through __dladdr, which no Sony module exports, so without this the
 * title would import a null call. There is no library to name: report
 * failure, which OpenSSL takes in its stride. */
struct Dl_info;
int __wrap_dladdr(const void *address, struct Dl_info *info)
{
    (void)address;
    (void)info;
    g2r_dlerror_message = "no dynamic libraries in the PS5 title";
    return 0;
}
